"""Build static English pages from the checked-in catalog and release manifest."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'public'
D=json.loads((OUT/'data/catalog.js').read_text(encoding='utf-8').removeprefix('window.PROMOD_DATA = ').rstrip(';\n'))
releases=json.loads((OUT/'downloads/manifest.json').read_text())
def page(file,title,description,body,scripts=False):
    nav=''.join(f'<a href="{href}"'+(' aria-current="page"' if href==file else '')+(' class="nav-download"' if href=='downloads.html' else '')+f'>{label}</a>' for href,label in [('index.html','Mods'),('crafting.html','Crafting'),('guide.html','Guide'),('downloads.html','Downloads')])
    content=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fafafa"><meta name="description" content="{html.escape(description,quote=True)}"><title>{title} — PRO MOD</title><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/site.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="shell header-inner"><a class="brand" href="index.html" aria-label="PRO MOD home">PRO <span>MOD</span></a><nav class="nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main><footer class="site-footer"><div class="shell"><div class="footer-top"><a class="brand" href="index.html">PRO <span>MOD</span></a><div class="footer-links"><a href="downloads.html">Downloads</a><a href="guide.html#installation">Installation</a><a href="https://github.com/filipjjd/promodmcsite">GitHub ↗</a><a href="downloads/THIRD-PARTY-NOTICES.txt">Credits</a></div></div><p>Mod created by <strong>FIFKO</strong></p><p class="fine-print">Independent Minecraft mods. Not an official Minecraft product. Not approved by or associated with Mojang or Microsoft. Minecraft Java 1.21.11 · Fabric · Java 21.</p></div></footer><div id="toast" role="status" hidden></div>{'<script src="data/catalog.js"></script>' if scripts else ''}<script src="assets/site.js" defer></script></body></html>'''
    (OUT/file).write_text(content,encoding='utf-8')
def head(kicker,title,lede):return f'<div class="page-head shell"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p class="lede">{lede}</p></div>'
apps=''.join(f'<div><svg aria-hidden="true"><use href="assets/ui.svg#{key}"/></svg>{label}</div>' for key,label in [('sms','Messages'),('phone','Phone'),('contacts','Contacts'),('notes','Notes'),('clock','Clock'),('camera','Camera'),('gallery','Gallery'),('calculator','Calculator'),('settings','Settings')])
phone=f'<div class="mini-phone" aria-label="Illustration of the ProTel home screen"><div class="island"></div><div class="phone-time">10:24</div><div class="phone-date">Your world. In your pocket.</div><div class="apps">{apps}</div><div class="phone-nav"><span>‹</span><span>○</span><span>□</span></div></div>'
home=f'''<section class="hero shell"><div class="eyebrow">Small details. A bigger world.</div><h1>PRO <span>MOD</span></h1><h2>Your world.<br>More possibilities.</h2><p>A phone in your pocket. A workshop of your own.<br>Discover a growing series of Minecraft mods built around communication, materials and machines.</p><div class="actions"><a class="button" href="downloads.html">Get the mods <span aria-hidden="true">↓</span></a><a class="button light" href="#mods">Explore the series ↘</a></div><div class="meta-strip"><span>MINECRAFT JAVA 1.21.11</span><span>FABRIC</span><span>CLIENT + SERVER</span></div></section>
<section class="section shell" id="mods"><div class="section-top"><div><div class="eyebrow">The collection</div><h2>Two mods.<br>One direction.</h2></div><p class="muted">Use either on its own.<br>Build your world with both.</p></div><div class="product-grid"><article class="product"><div class="product-art">{phone}<span class="illustration-label">INTERFACE ILLUSTRATION · THEMES AVAILABLE IN GAME</span></div><div class="product-body"><div class="version">01 / COMMUNICATION · v1.2.2</div><h3>ProTel</h3><p>A smartphone that belongs in your world. Call friends, send messages, take photos and make it your own.</p><div class="actions"><a class="button" href="downloads.html#protel">Download ProTel ↓</a><a class="text-link" href="#protel">Meet your phone →</a></div></div></article><article class="product"><div class="product-art"><div class="material-art"><img class="pixel" src="assets/items/propylene_ingot.png" alt="Propylene ingot"><img class="machine" src="assets/items/electric_press.svg" alt="Electric press model illustration"><img class="pixel" src="assets/items/propylene_sheet.png" alt="Propylene sheet"></div><span class="illustration-label">FROM RAW MATERIAL TO FINISHED COMPONENT</span></div><div class="product-body"><div class="version">02 / PRODUCTION · v0.2.4</div><h3>Materials</h3><p>The foundation of your workshop. Six minerals, new components and two presses to turn resources into something useful.</p><div class="actions"><a class="button" href="downloads.html#materials">Download Materials ↓</a><a class="text-link" href="#materials">Explore the workshop →</a></div></div></article></div></section>
<section class="section shell split" id="protel"><div><div class="eyebrow">ProTel / v1.2.2</div><h2>A little closer.<br>Even worlds apart.</h2><p class="lede">A real number, a physical SIM card and your friends on the same server.</p><a class="text-link" href="guide.html#phone">Set up your first phone →</a></div><div class="details-grid"><article class="feature"><h3>Calls & messages</h3><p>Register a number such as t1234. Exchange SMS and start voice calls with online players, even across dimensions.</p></article><article class="feature"><h3>Make it yours</h3><p>Choose a theme and font, arrange your app icons and use multiple home-screen pages. The phone follows your Minecraft language.</p></article><article class="feature"><h3>Capture the moment</h3><p>Use the camera, switch to selfie mode and keep your pictures in the gallery. Photos are saved locally.</p></article><article class="feature"><h3>Everyday essentials</h3><p>Notes, contacts, a calculator, real-time alarms, a stopwatch and a timer. Quick settings and volume controls are a swipe away.</p></article></div></section>
<section class="section shell split" id="materials"><div><div class="eyebrow">Materials / v0.2.4</div><h2>Start with a vein.<br>Build a workshop.</h2><p class="lede">Zinc, bronze, chromium, platinum, silicon and propylene. A distinct resource for every next step.</p><a class="text-link" href="crafting.html">Open the recipe book →</a></div><div><div class="details-grid"><article class="feature"><h3>Six materials</h3><p>Stone and deepslate variants, with one smelted material per ore block. Bronze and propylene are intentionally fictional ores.</p></article><article class="feature"><h3>Two ways to press</h3><p>Use coal for your first machine, or supply compatible energy to an electric press. Both turn propylene into sheets.</p></article><article class="feature"><h3>Shared ingredients</h3><p>Recipes accept correctly tagged equivalent materials from other mods, including different kinds of planks.</p></article><article class="feature"><h3>Shallower discoveries</h3><p>Since v0.2.2, platinum and silicon generate between Y=−6 and Y=16. Chromium remains the rarest material, deep underground.</p></article></div><div class="callout">New ores appear in newly generated Overworld chunks. Existing terrain is left untouched.</div></div></section>
<section class="dark-band"><div class="shell"><div><div class="eyebrow" style="color:#aaa">Built for your next idea</div><h2>Know what goes where.</h2><p>Crafting grids, machine instructions and a practical mining guide.</p></div><a class="button" href="guide.html">Explore the guide →</a></div></section>
<section class="section shell"><div class="eyebrow">In development</div><h2>More to come.</h2><p class="lede">Internet services, an app store and connected Wi-Fi or Bluetooth devices are planned for cooperating mods. The current releases focus on phones, communication, materials and presses.</p><p class="muted">Phone and SIM crafting recipes will arrive later. For now, get them in Creative or with commands.</p></section>'''
page('index.html','Your world. More possibilities.','ProTel smartphones and Materials machines for Minecraft Java 1.21.11 Fabric. Download the mods, explore recipes and get started.',home)

craft=head('The workshop / recipe book','Make something useful.','Real recipes from Materials 0.2.4. Choose an item to see its crafting grid, ingredients and processing details.')+'''<section class="shell"><div class="toolbar"><label class="search"><input type="search" id="search" aria-label="Search recipes" placeholder="Search zinc, press, wire…"></label><div class="filters" aria-label="Recipe filters"><button class="filter" data-filter="all" aria-pressed="true">All recipes</button><button class="filter" data-filter="craft" aria-pressed="false">Crafting</button><button class="filter" data-filter="press" aria-pressed="false">Pressing</button><button class="filter" data-filter="smelt" aria-pressed="false">Smelting</button></div></div><div class="count" id="recipe-count" aria-live="polite"></div><div class="recipe-cards" id="recipe-cards"></div><div class="empty" id="empty" hidden>No matching recipes. Try another name or choose “All recipes”.</div><noscript><p>Enable JavaScript for the interactive recipe book, or open the <a href="downloads/RECIPES.txt">plain-text recipes</a>.</p></noscript><div class="callout">Any planks can be mixed. Equivalent ingredients from other mods need the matching material tag. “Alloy” refers to the existing smelted ingot; there is no extra alloying step.</div><p class="muted">Looking for phone crafting? ProTel phones and SIM cards currently come from Creative or commands. <a class="text-link" href="guide.html#phone">See how →</a></p></section><dialog class="dialog" id="recipe-dialog" aria-labelledby="recipe-title"><div class="dialog-head"><div><div class="eyebrow" id="recipe-type"></div><h2 id="recipe-title"></h2></div><button class="close" aria-label="Close recipe">×</button></div><div class="dialog-body" id="recipe-detail"></div></dialog>'''
page('crafting.html','Crafting','Search ProMod Materials recipes: copper wire, propylene sheets, coal and electric presses, and smelting.',craft,True)

ore_rows=''.join(f'<tr><td><span class="ore-name"><img src="assets/items/{m}_ore.png" alt="" loading="lazy">{b["name"]}</span></td><td>{b["rarity"]}</td><td>{b["range"][0]} to {b["range"][1]}</td><td>{b["best"]}</td><td>{b["tool"]}</td></tr>' for m,b in D['balance'].items())
guide=head('Field notes / getting started','A little guidance.<br>A lot of possibilities.','From your first SIM card to a powered press. Find the steps, requirements and small details that make everything work.')+f'''<div class="shell guide-layout"><aside class="guide-nav" aria-label="Guide sections"><a href="#installation">01 / Installation</a><a href="#phone">02 / Your first phone</a><a href="#mining">03 / Where to mine</a><a href="#machines">04 / Machines</a><a href="#compatibility">05 / Compatibility</a><a href="#faq">06 / Troubleshooting</a></aside><div class="guide-content">
<section id="installation"><div class="eyebrow">01 / Before you start</div><h2>Install once. Play together.</h2><ol><li>Use <strong>Minecraft Java 1.21.11</strong> with <strong>Java 21</strong> and <a href="https://fabricmc.net/use/installer/">Fabric Loader</a> 0.18.1 or newer.</li><li>Install <a href="https://modrinth.com/mod/fabric-api/versions?g=1.21.11">Fabric API for 1.21.11</a>.</li><li>Download ProTel, Materials, or both. Put the JAR files in your Minecraft instance’s <code>mods</code> folder.</li><li>For multiplayer, install the same mods and Fabric API on <strong>the server and every player’s client</strong>. Restart the game and server.</li></ol><div class="callout">Keep only one version of each mod in the mods folder. ProTel 1.2.2 replaces older TELPRO / modtel JARs. Its internal <code>modtel</code> ID is retained for existing items and saves.</div><p>These are Fabric builds. They are not NeoForge or Forge builds. ProTel and Materials can currently be installed independently.</p><a class="text-link" href="downloads.html">Go to downloads →</a></section>
<section id="phone"><div class="eyebrow">02 / ProTel</div><h2>Your first number.</h2><ol><li>Get a smartphone and SIM card from Creative, or use the commands below.</li><li>Keep the phone in your inventory and press <kbd>P</kbd> (default binding).</li><li>Open <strong>Settings → SIM card</strong> and insert your physical SIM.</li><li>Choose four digits and register. Your number has the format <strong>t1234</strong>. Numbers must be unique in the world.</li><li>Ask a friend on the same server to register their own SIM. Open Messages or Phone and enter their number.</li></ol><pre class="commands"><code>/give @s modtel:smartphone
/give @s modtel:sim_card
/give @s modtel:sim_card_3g
/give @s modtel:sim_card_5g</code></pre><h3>Messages & voice</h3><p>The recipient must be online on the same server and have a phone with an inserted, registered SIM. 3G, 4G and 5G cards all support calls and SMS. A loose SIM in your inventory does not activate the phone.</p><p>After a call is accepted, use the microphone button to start talking. <strong>The microphone starts muted for each call.</strong> Your phone’s volume slider controls call audio and ringtones; Minecraft’s master volume also applies. Calls use the game connection, with no separate voice mod or extra port.</p><p>Closing the phone window does not hang up. Removing the SIM, losing the phone, dying or leaving the server ends the call. SMS messages are limited to 1,000 characters; undelivered messages stay as drafts. Offline delivery is not available yet.</p><h3>Photos, notes & alarms</h3><p>The camera supports moving the view, selfies and gallery storage. Alarms use real-world time and work while the game is running. Use the Clock app for timers and a stopwatch.</p><p>Photos are stored in <code>config/modtel/local/photos</code>. Local phone data is stored in <code>config/modtel/local/phone.json</code>. SIM registration is stored with the world. Back up both when moving installations.</p><p>Built-in apps are protected from uninstalling. Use the layout control in quick settings to rearrange apps and move them between pages.</p></section>
<section id="mining"><div class="eyebrow">03 / Materials 0.2.4</div><h2>Find your next vein.</h2><p>All six materials generate in new Overworld chunks, with stone and deepslate ore variants. Platinum and silicon now sit much closer to the surface.</p><div class="ore-table-wrap"><table class="ore-table"><thead><tr><th>Material</th><th>Rarity</th><th>Y range</th><th>Look around Y</th><th>Minimum pickaxe</th></tr></thead><tbody>{ore_rows}</tbody></table></div><div class="callout"><strong>Changed in 0.2.2:</strong> platinum and silicon are limited to Y=−6 through Y=16. Their upper limit is unchanged. Ore origins are inset so the edges of veins stay inside that band.</div><h3>Mine smarter</h3><ul><li><strong>Start with zinc and bronze.</strong> They are common workshop materials, balanced around ordinary underground iron and copper.</li><li><strong>Try Y=5 for platinum and silicon.</strong> Their total frequency remains rare, but their new narrow band makes focused mining worthwhile.</li><li><strong>Chromium is the rarest.</strong> Look deep underground and dig tunnels; exposed cave surfaces hide much of its potential generation.</li><li><strong>Propylene behaves like deep gold.</strong> Aim around Y=−48. It has no badlands bonus.</li><li><strong>Smelt the ore block.</strong> Each ore drops itself and makes one ingot. Fortune does not increase the drop. A furnace takes 10 seconds; a blast furnace takes 5 at 20 TPS.</li></ul><p>Rarity comparisons are design targets, not guaranteed counts. Terrain, caves and neighboring veins affect results. Old chunks retain their original ores; explore new terrain to see the new distribution.</p><p>Bronze and propylene ores are fictional materials by design.</p></section>
<section id="machines"><div class="eyebrow">04 / Production</div><h2>Press ahead.</h2><p>Both ProMod presses turn <strong>one propylene ingot into one propylene sheet</strong>. The coal press takes 100 ticks (5 seconds); the electric press takes 20 ticks (1 second), at 20 TPS. Right-click a press, place the material in the left slot and collect the output on the right.</p><article class="machine-row"><img src="assets/items/coal_press.svg" alt="Coal press"><div><h3>Coal press</h3><p>Your first machine. Insert coal, charcoal or a coal block into the fuel slot.</p><div class="stats"><div><strong>5 s</strong><span>per sheet</span></div><div><strong>16</strong><span>sheets per coal</span></div><div><strong>160</strong><span>sheets per coal block</span></div></div><p>Hoppers: input from above, fuel from the sides, output from below. Fuel is consumed only while processing.</p><a class="text-link" href="crafting.html#coal_press">View crafting →</a></div></article><article class="machine-row"><img src="assets/items/electric_press.svg" alt="Electric press"><div><h3>Electric press</h3><p>Supply power from a compatible external energy source. The machine accepts Team Reborn Energy API energy from all six sides.</p><div class="stats"><div><strong>1 s</strong><span>per sheet</span></div><div><strong>800 E</strong><span>per sheet</span></div><div><strong>40 E/t</strong><span>while running</span></div><div><strong>16,000 E</strong><span>energy buffer</span></div></div><p>Hoppers: input from above or the sides, output from below. The machine does not output energy.</p><a class="text-link" href="crafting.html#electric_press">View crafting →</a></div></article><div class="callout">ProMod does not add a generator or placeable power cables yet. Copper wire is a crafting ingredient. Energy API is bundled with Materials; Fabric API is still a separate requirement.</div><p>A full output slot or missing input pauses work without wasting fuel or energy. Machines save their inventories, progress and stored resources. Breaking a machine drops its items; stored energy is lost.</p></section>
<section id="compatibility"><div class="eyebrow">05 / Works with your workshop</div><h2>Shared materials.<br>Specific integrations.</h2><p>Craftings accept common tags such as <code>c:ingots/zinc</code>, <code>c:ingots/platinum</code>, <code>c:ingots/bronze</code>, <code>c:wires/copper</code> and <code>minecraft:planks</code>. Equivalent ores and raw materials can be smelted, too. Our materials also populate legacy forge and flat Fabric tags, so other mods can use them in tag-based recipes. Chrome/chromium aliases and the shared c:silicon tag are recognized in both directions.</p><p>The item must carry the right tag; a similar name alone is not enough. Bronze is different from brass. When another mod provides its own smelting recipe, Minecraft may select that mod’s equivalent ingot.</p><h3>JEI and REI recipe browsing</h3><p>Install one optional recipe viewer for Minecraft 1.21.11 Fabric: <a href="https://modrinth.com/mod/jei">JEI</a> or <a href="https://modrinth.com/mod/rei">REI</a>. Both show separate coal press, electric press and wire cutting categories, including inputs, outputs, processing time and shears wear. Server-synchronized press recipes include datapack additions.</p><p>Tested with JEI 27.4.0.16 and REI 21.11.816. REI also needs Architectury 19.0.1 and Cloth Config 21.11.153. Install the viewer on your client; install Materials and Fabric API on the server and clients. Materials requires Fabric API 0.141.6+1.21.11 or a newer build for 1.21.11. Materials works without either viewer, and neither is bundled. Automatic ingredient transfer into presses is not included.</p><p>There is no official EMI release for 1.21.11 in the checked version catalog, so this release does not claim EMI support. Always choose the Fabric build for your exact Minecraft version.</p><h3>Create Fly pressing</h3><p>With Create Fly installed, its mechanical press can also turn a propylene ingot into a sheet. Processing speed depends on the Create machine. The recipe is loaded only when Create is present; it was checked with Create Fly 6.0.9-5 for 1.21.11.</p><p>Other mods’ machines need their own recipe integrations. Shared energy or material tags alone do not add the sheet recipe to every press.</p></section>
<section id="faq" class="faq"><div class="eyebrow">06 / Good to know</div><h2>A few quick answers.</h2><details><summary>Does the server need the mods?</summary><p>Yes. Install the chosen ProMod JARs and Fabric API on the server and all clients. Single-player LAN also works when every participant has the required mods.</p></details><details><summary>Why can’t I find the new ores?</summary><p>Explore newly generated Overworld chunks. Existing chunks are not regenerated. Check the Y ranges above and make sure the server is running Materials 0.2.4.</p></details><details><summary>Why does my call have no sound?</summary><p>Accept the call, enable the in-call microphone on the speaking side, then check phone and Minecraft volume. ProTel uses your system’s default audio devices. Headphones help avoid echo. Voice packets were tested with synthetic audio; real microphones and drivers can behave differently.</p></details><details><summary>Why is my phone out of service?</summary><p>Insert a registered SIM into the phone through Settings. Keep the phone in your inventory. An unregistered or loose SIM will not provide service.</p></details><details><summary>Is there an app store or internet?</summary><p>Not in these releases. Internet, an app store, Wi-Fi infrastructure and Bluetooth devices are planned for future cooperating mods. Their interface elements do not currently provide those services.</p></details><details><summary>Why does my electric press do nothing?</summary><p>Provide a compatible external energy source, a propylene ingot and space in the output slot. A copper wire item cannot transmit power. Try the coal press if you have no compatible generator.</p></details><details><summary>Can I craft the phone or SIM?</summary><p>Not yet. Use Creative or the commands in the phone setup section. The recipe book covers the recipes that exist today.</p></details><details><summary>Where should I report a problem?</summary><p><a href="https://github.com/filipjjd/promodmcsite/issues">Open an issue on GitHub</a> with the Minecraft version, mod versions, steps to reproduce and relevant log lines. Remove server addresses or personal information you do not want to share.</p></details></section>
</div></div>'''
page('guide.html','Guide','Install ProMod, register a SIM, place a press and find the right mining levels. Practical guides for ProTel and Materials.',guide)

cards=''
for r in releases:
    phone=r['id']=='promod-protel';name='ProTel' if phone else 'Materials';anchor='protel' if phone else 'materials'
    description='Smartphones, registered SIM cards, SMS, voice calls, camera and everyday apps.' if phone else 'Six materials, twelve ore blocks, copper wire, propylene sheets and two presses.'
    cards+=f'''<article class="download-card" id="{anchor}"><div class="eyebrow">{'Communication' if phone else 'Production'}</div><h2>{name} <span class="version">v{r['version']}</span></h2><p>{description}</p><span class="pill">MC 1.21.11</span><span class="pill">FABRIC</span><span class="pill">JAVA 21</span><div><a class="button" href="{r['file']}" download>Download {name} ↓</a></div><code>{Path(r['file']).name} · {r['bytes']/1024:.1f} KiB</code><p>Required on client and server. Fabric API is required separately.</p><details><summary>SHA-256 checksum</summary><code>{r['sha256']}</code></details></article>'''
downloads=head('Official project files','Ready for your world.','Choose your mods. Install the matching Fabric API. Start exploring. These are development releases for Minecraft Java 1.21.11.')+f'''<section class="shell"><div class="download-grid">{cards}</div><div class="callout">Replace the previous JAR for each mod; do not leave multiple versions in the mods folder. The two mods are currently independent. Back up your world before updating.</div><div class="actions"><a class="button light" href="https://modrinth.com/mod/fabric-api/versions?g=1.21.11">Get Fabric API ↗</a><a class="text-link" href="https://fabricmc.net/use/installer/">Fabric installer ↗</a><a class="text-link" href="downloads/SHA256SUMS.txt">All checksums</a></div></section><section class="section shell"><div class="eyebrow">Three steps</div><h2>From download to first launch.</h2><div class="checklist"><article><h3>01. Match your version</h3><p>Use Minecraft Java 1.21.11, Java 21 and Fabric Loader 0.18.1 or newer.</p></article><article><h3>02. Add the files</h3><p>Put your ProMod JARs and matching Fabric API in the instance’s mods folder.</p></article><article><h3>03. Bring your friends</h3><p>For multiplayer, install the same files on the server and every player’s client.</p></article></div><a class="text-link" href="guide.html#installation">Full installation guide →</a><p>Want in-game recipes? Add optional JEI or REI. <a class="text-link" href="guide.html#compatibility">Versions and dependencies →</a></p></section><section class="section shell"><div class="eyebrow">Release notes</div><h2>What’s changed.</h2><article class="update"><div class="version">MATERIALS 0.2.4<br>02 NOV 2026</div><div><h3>A better-connected workshop.</h3><p>Optional JEI and REI categories show both presses and copper wire cutting, including server-synchronized datapack recipes. Expanded shared tags let equivalent materials work across mods, with legacy Fabric and forge tags, chrome/chromium aliases and shared silicon support.</p></div></article><article class="update"><div class="version">MATERIALS 0.2.3<br>01 NOV 2026</div><div><h3>Electric pressing, five times faster.</h3><p>The electric press now makes a sheet in 1 second (20 ticks). The coal press takes 5 seconds (100 ticks). Electric energy cost stays at 800 E per sheet, with a draw of 40 E/t. Progress bars and translated machine labels follow the correct speed.</p></div></article><article class="update"><div class="version">MATERIALS 0.2.2<br>01 NOV 2026</div><div><h3>Rare minerals, closer to the surface.</h3><p>Platinum and silicon now generate from Y=−6 to Y=16. Their upper limit is unchanged, and the other four materials keep their existing distributions. Applies to newly generated chunks.</p></div></article><article class="update"><div class="version">MATERIALS 0.2.1</div><div><h3>A better-balanced underground.</h3><p>Chromium became the rarest material. Zinc and bronze became common workshop resources; propylene moved deep underground.</p></div></article><article class="update"><div class="version">MATERIALS 0.2.0</div><div><h3>Your first production line.</h3><p>Copper wire, propylene sheets, coal and electric presses, shared ingredient tags and optional Create Fly pressing support.</p></div></article><article class="update"><div class="version">PROTEL 1.2.2</div><div><h3>Stay in touch.</h3><p>Registered physical SIM cards, player-to-player SMS and voice calls. ProTel retains the internal modtel ID for existing data. Internet and the app store remain future features.</p></div></article></section>'''
page('downloads.html','Downloads','Download ProTel 1.2.2 and Materials 0.2.4 for Minecraft 1.21.11 Fabric. Includes installation instructions and SHA-256 checksums.',downloads)
page('404.html','Page not found','This page could not be found.',head('404 / A small detour','This block is missing.','The page may have moved. Head back to the project or open the recipe book.')+'<div class="shell actions"><a class="button" href="index.html">Back to home</a><a class="button light" href="crafting.html">Open recipes</a></div>')
(OUT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#111"/><path d="M20 46V18h14c17 0 17 20 0 20h-6v8zm8-16h6c6 0 6-5 0-5h-6z" fill="white"/></svg>')
print('Built 5 English HTML pages.')
